package com.hbm.client.missile.launchpad.standard;
import com.hbm.client.gui.LegacyContainerScreen;import com.hbm.client.missile.completion.MissileRenderer;import com.hbm.item.fluid.client.FluidInfo;import com.hbm.missile.completion.MissileContent;import com.hbm.missile.launchpad.standard.*;import com.mojang.blaze3d.platform.Lighting;import com.mojang.blaze3d.systems.RenderSystem;import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;import java.util.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.entity.player.Inventory;import org.joml.Matrix3f;import org.joml.Vector3f;
/** Original176x236 GUI, all seven slots, ready arrows and actual source-form 3D missile preview. */
public final class StandardLaunchPadScreen extends LegacyContainerScreen<StandardLaunchPadMenu>{public StandardLaunchPadScreen(StandardLaunchPadMenu menu,Inventory player,Component title){super(menu,player,title,ResourceLocation.parse("hbm:textures/gui/weapon/gui_launch_pad_large.png"),176,236);}private StandardLaunchPadBlockEntity machine(){return minecraft.level!=null&&minecraft.level.getBlockEntity(menu.position()) instanceof StandardLaunchPadBlockEntity p?p:null;}@Override public void renderBackground(GuiGraphics g,int x,int y,float partial){g.fillGradient(0,0,width,height,0xc0101010,0xd0101010);renderBg(g,partial,x,y);}@Override protected void renderLabels(GuiGraphics g,int x,int y){g.drawString(font,title,88-font.width(title)/2,4,4210752,false);g.drawString(font,playerInventoryTitle,8,142,4210752,false);}
 @Override protected void renderBg(GuiGraphics g,float partial,int x,int y){super.renderBg(g,partial,x,y);var m=machine();if(m==null)return;for(int i=0;i<2;i++){int ready=m.getGaugeState(i);if(ready!=0)drawLegacyRegion(g,130+i*18,23,ready==1?192:198,0,6,8);}drawLegacyRegion(g,112,23,m.power>=75000?192:198,0,6,8);int fill=(int)(m.power*52/StandardLaunchPadBlockEntity.MAX_POWER);if(fill>0)drawLegacyRegion(g,107,88-fill,176,52-fill,16,fill);for(int i=0;i<2;i++)tank(g,m.tanks[i],125+i*18);var kind=MissileContent.kind(menu.getSlot(0).getItem());if(kind!=null)preview(g,kind);String key=switch(m.state){case StandardLaunchPadBlockEntity.LOADING->"loading";case StandardLaunchPadBlockEntity.READY->"ready";default->"missing";};float scale=m.state==0?.5F:m.state==1?.6F:.8F;int color=m.state==0?0xff0000:m.state==1?0xff8000:0x00ff000;var label=Component.translatable("gui.hbm.launch_pad."+key);var poses=g.pose();poses.pushPose();poses.translate(leftPos+34,topPos+107,0);poses.scale(scale,scale,1);g.drawString(font,label,-font.width(label)/2,-font.lineHeight/2,color,false);poses.popPose();}
 private void tank(GuiGraphics g,com.hbm.fluid.FluidTank tank,int offset){int height=tank.getFill()*52/Math.max(tank.getMaxFill(),1);if(height<=0)return;g.flush();int color=tank.getTankType().getTint();RenderSystem.setShader(GameRenderer::getPositionTexColorShader);RenderSystem.setShaderTexture(0,tank.getTankType().getTexture());RenderSystem.enableBlend();RenderSystem.defaultBlendFunc();var out=Tesselator.getInstance().begin(VertexFormat.Mode.QUADS,DefaultVertexFormat.POSITION_TEX_COLOR);var matrix=g.pose().last().pose();int x=leftPos+offset,y=topPos+88;out.addVertex(matrix,x,y,0).setUv(0,1).setColor(color>>16&255,color>>8&255,color&255,255);out.addVertex(matrix,x+16,y,0).setUv(1,1).setColor(color>>16&255,color>>8&255,color&255,255);out.addVertex(matrix,x+16,y-height,0).setUv(1,1-height/16F).setColor(color>>16&255,color>>8&255,color&255,255);out.addVertex(matrix,x,y-height,0).setUv(0,1-height/16F).setColor(color>>16&255,color>>8&255,color&255,255);BufferUploader.drawWithShader(out.buildOrThrow());RenderSystem.disableBlend();}
 private void preview(GuiGraphics g,MissileContent.Kind kind){g.flush();var poses=g.pose();poses.pushPose();poses.translate(leftPos+70,topPos+120,100);poses.mulPose(Axis.YP.rotationDegrees(90));float scale=switch(kind.form){case ABM->1.45F;case V2->1.75F;case STRONG->1.375F;case HUGE->.925F;case ATLAS->.875F;default->1;};poses.scale(scale*-8,scale*-8,scale*-8);var lights=new Matrix3f(poses.last().normal()).rotateY((float)Math.toRadians(75));RenderSystem.setShaderLights(lights.transform(new Vector3f(.2F,1,-.7F).normalize()).normalize(),lights.transform(new Vector3f(-.2F,1,.7F).normalize()).normalize());MissileRenderer.model(kind,poses,g.bufferSource(),LightTexture.FULL_BRIGHT,OverlayTexture.NO_OVERLAY,true);g.flush();poses.popPose();Lighting.setupFor3DItems();}
 @Override public void render(GuiGraphics g,int x,int y,float partial){super.render(g,x,y,partial);var m=machine();if(m==null)return;if(legacyInfoHovered(x,y,107,36,16,52))g.renderTooltip(font,Component.literal(String.format(Locale.US,"%,d / %,d HE",m.power,StandardLaunchPadBlockEntity.MAX_POWER)),x,y);for(int i=0;i<2;i++)if(legacyInfoHovered(x,y,125+i*18,36,16,52)){var tank=m.tanks[i];var lines=new ArrayList<Component>();lines.add(tank.getTankType().displayName());lines.add(Component.literal(tank.getFill()+" / "+tank.getMaxFill()+" mB"));FluidInfo.append(tank.getTankType(),lines,hasShiftDown());g.renderComponentTooltip(font,lines,x,y);}if(menu.getCarried().isEmpty()&&menu.getSlot(1).getItem().isEmpty()&&legacyInfoHovered(x,y,26,72,16,16))com.hbm.client.designator.DesignatorHints.render(g,font,width,height,x,y);}
}
